import { View, Text, FlatList, StyleSheet } from "react-native";
import { registerRootComponent } from "expo";

const PRODUCTS = [
  { id: "p1", name: "Утасгүй чихэвч", price: "159,000₮" },
  { id: "p2", name: "Гар цаг X100", price: "249,000₮" },
  { id: "p3", name: "Нарны шил", price: "89,000₮" },
  { id: "p4", name: "Арьсан цүнх", price: "199,000₮" },
];

function App() {
  return (
    <FlatList
      style={styles.list}
      data={PRODUCTS}
      keyExtractor={(item) => item.id}
      ListHeaderComponent={
        <View nativeID="list-header" style={styles.header}>
          <Text style={styles.headerTitle}>Бүх бараа</Text>
        </View>
      }
      renderItem={({ item }) => (
        <View testID="product" style={styles.row}>
          <Text style={styles.name}>{item.name}</Text>
          <Text style={styles.price}>{item.price}</Text>
        </View>
      )}
    />
  );
}

const styles = StyleSheet.create({
  list: { flex: 1, backgroundColor: "#f8fafc" },
  header: { padding: 16, backgroundColor: "#2563eb" },
  headerTitle: { color: "#fff", fontSize: 20, fontWeight: "bold" },
  row: { flexDirection: "row", justifyContent: "space-between", padding: 16, backgroundColor: "#fff" },
  name: { fontSize: 16 },
  price: { fontSize: 16, fontWeight: "bold", color: "#2563eb" },
});

registerRootComponent(App);
